DataManager._asCheatMenu_saveInRollMin = 2;
DataManager._asCheatMenu_saveInRollMax = 6;
if (!('_asCheatMenu_saveInRollCurrent' in DataManager)) {
DataManager._asCheatMenu_saveInRollCurrent = 0;
}
if (DataManager._asCheatMenu_saveInRollCurrent < DataManager._asCheatMenu_saveInRollMin) {
DataManager._asCheatMenu_saveInRollCurrent = DataManager._asCheatMenu_saveInRollMin;
} else if (DataManager._asCheatMenu_saveInRollCurrent > DataManager._asCheatMenu_saveInRollMax) {
DataManager._asCheatMenu_saveInRollCurrent = DataManager._asCheatMenu_saveInRollMax;
}
DataManager.saveGame(DataManager._asCheatMenu_saveInRollCurrent++);
SoundManager.playSystemSound(1);

var actors = $gameParty.allMembers();
for (var i = 0; i < actors.length; i++) {
var actor = actors[i];
if (!actor) continue;
actor.setHp(actor.mhp);
}
SoundManager.playSystemSound(1);

var actors = $gameParty.allMembers();
for (var i = 0; i < actors.length; i++) {
var actor = actors[i];
if (!actor) continue;
actor.setMp(actor.mmp);
}
SoundManager.playSystemSound(1);

var actors = $gameTroop.members();
for (var i = 0; i < actors.length; i++) {
var actor = actors[i];
if (!actor) continue;
if (actor._hp <= 0) continue;
actor.setHp(1);
}
SoundManager.playSystemSound(1);

var actors = $gameTroop.members();
for (var i = 0; i < actors.length; i++) {
var actor = actors[i];
if (!actor) continue;
if (actor._hp <= 0) continue;
actor.setHp(0);
}
SoundManager.playSystemSound(1);

if (!window.SceneManager) return;
var scene = SceneManager._scene;
if (!scene) return;
var windowName = decodeURIComponent('');
if (windowName) {
scene = scene[windowName];
if (!scene) return;
}
if (!(scene instanceof Window_Selectable)) {
var found = Object.entries(scene).reverse().find(([name, value]) => value instanceof Window_Selectable && value.visible);
scene = found[1];
}
if (!scene) return;
var index = parseInt('0');
if (isNaN(index) || index < 0) {
alert('Invalid index');
}
scene._index = parseInt('0');
scene.processOk();

